let colors=['#e2942f','#d95655','#1866a7','#68a145','#2f4f82']
let simplex

function setup() {
	let w= max(windowWidth, windowHeight) 
	createCanvas(w, w);
	simplex = new OpenSimplexNoise(Date.now());
	randomSeed(1)
}

function draw(){	
	background(colors[4]);
	translate(width/2, height/2)
	noStroke()
let colorPicker=0
for(let a=TAU/40; a<TAU+TAU/40; a+=TAU/20){
	emmision(a, a+TAU/20, colorPicker%5)
	colorPicker++
}



fill(0)

	for(let a=0; a<TAU; a+=TAU/20){
	 for(let d=width/6; d<width*0.75; d+=width/12){
		 let sizer= map(d, width/8, width*0.75, width/75, width/20)
		 let dOffset= map(simplex.noise3D(a/10, d/200, frameCount/50), -1, 1, -sizer/2, sizer/2)
		 let aOffset= map(simplex.noise3D(d/200, cos(a/10), frameCount/50), -1, 1, -TAU/40, TAU/40)

		 pdot(cos(a+aOffset)*d+ dOffset, sin(a+aOffset)*d+dOffset, sizer)

	 }


	}
	fill('#b4032e')
	pdot(0, 0, width/8)
}


function emmision(beginA, endA, colorIndex){
	fill(colors[colorIndex])
	beginShape()
	vertex(0, 0)
	for(let d=1; d<width*0.75; d+=5){
		//let dOffset= map(simplex.noise3D(a/10, d/200, frameCount/50), -1, 1, -sizer/2, sizer/2)
		let aOffset= map(simplex.noise3D(d/200, cos(beginA/10), frameCount/50), -1, 1, -TAU/40, TAU/40)
		vertex(cos(beginA+aOffset)*d, sin(beginA+aOffset)*d)
	}

	for(let d=width*0.75; d>0; d-=5){
		let aOffset= map(simplex.noise3D(d/200, cos(endA/10), frameCount/50), -1, 1, -TAU/40, TAU/40)
		vertex(cos(endA+aOffset)*d, sin(endA+aOffset)*d)	
	}
	endShape(CLOSE)

}




function pdot(x, y, r){
	push()
		translate(x, y)
		beginShape()
	randomSeed(r)
	let xOffer=random(1000)
	let yOffer= random(1000)
	// let r= width/8
		for(let a=0; a<=TAU; a+=TAU/100){
			let xoff=map(simplex.noise3D(cos(a), xOffer, frameCount/50), -1, 1, -r/4, r/4)
			let yoff=map(simplex.noise3D(sin(a), yOffer, frameCount/50), -1, 1, -r/4, r/4)
			curveVertex(cos(a)*(r+ xoff), sin(a)*(r+yoff))

		}
		endShape(CLOSE)
		pop()


}
